// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(bytes4 interfaceId) public {
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool result) {
            ok = result;
        } catch {
            ok = false;
        }
        assertTrue(ok ? c.supportsInterface(type(IERC1155).interfaceId) : true);
    }
}

interface IERC1155 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
